#!/bin/sh
# Tier 1 wrapper for Codex, profile ${PROFILE_NAME}.
#
# CODEX_HOME is the real mechanism (measured 2026-09-18): it relocates
# config, logs and the sqlite state, while the runtime package stays shared.
# Generated by devkit; edits are lost on `devkit profile sync`.
set -eu
CODEX_HOME="${PROFILE_CONFIG_DIR}"
export CODEX_HOME
exec codex "$@"
